var LOCAL_HOSTS=new Set(["localhost","127.0.0.1","::1"]);function isLocalDevHost(hostname){return LOCAL_HOSTS.has(String(hostname||"").toLowerCase())}function normalizeBaseUrl(value){return String(value||"").trim().replace(/\/+$/,"")}function resolveRuntimeOverride({hostname,searchParams,key,fallback}){const normalizedFallback=normalizeBaseUrl(fallback);if(!isLocalDevHost(hostname))return normalizedFallback;return normalizeBaseUrl(searchParams?.get?.(key))||normalizedFallback}export{isLocalDevHost,resolveRuntimeOverride};
